export type AgentLogoEntry = {
  /** Stable id, used as the React key. */
  id: string
  /** Name of the agent: read by the screen reader, shown on hover. */
  name: string
  /** Size of the mark: every one is 24 px tall, the width follows the art. */
  className: string
  /** The glyph itself. */
  Glyph: (props: { className?: string }) => React.ReactElement
}

/** The agents this app can be connected to, in the order they are listed. */
export const AGENT_LOGOS: AgentLogoEntry[] = [
  { id: 'claude-code', name: 'Claude Code', className: 'size-6', Glyph: ClaudeLogo },
  { id: 'codex', name: 'Codex', className: 'size-6', Glyph: CodexLogo },
  // The wing is twice as tall as it is wide: same height, narrower box.
  { id: 'hermes', name: 'Hermes', className: 'h-6 w-3', Glyph: HermesLogo },
  { id: 'cursor', name: 'Cursor', className: 'size-6', Glyph: CursorLogo },
  { id: 'gemini', name: 'Gemini', className: 'size-6', Glyph: GeminiLogo },
]
